head.script:
let curID = '';
let oldID = '';


// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[key > P > id]<br/>DataMap 모듈의 Key ID 를 설정합니다.",
    "validation" : [
        "동일 Scope 에서 DataMap 모듈의 Key ID 를 구별할 수 있는 유일값을 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    curID = con_ID.getText();

    // 기존 target 있으면 삭제
    if (typeof scwin[oldID] !== 'undefined') {
        $p.data.remove(oldID);
    }    

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // target 생성
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:dataMap ' + strNameSpace + ' id="dataMap1" baseNode="map">';        
    strTarget += '<w2:keyInfo>';
    strTarget += '<w2:key id="'+ curID +'" dataType="text" name="name1"></w2:key>';
    strTarget += '</w2:keyInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<'+ curID +'><![CDATA[dm_data1]]></'+ curID +'>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataMap>';

    // target 생성
    $p.data.create(strTarget);

    let arrResult = $p.data.getAllDataCollection("object");
    scwin[curID] = arrResult[arrResult.length-1];

    oldID = curID;

    // input 생성
    $c.gcm.createEmptyInput('ref="data:dataMap1.'+ curID +'" style="width:200px;"', '', 'input1')

    scwin.btn_getID_onclick();
}



scwin.btn_getID_onclick = function (e) {
    let rtn = $p.data.getInfo(["mf_dataMap1"]);

    let id = eval("rtn.mf_dataMap1.keyInfo." + curID + ".id");

    wf_body_bottom.getObj("scwin").setReturnValue("id : " +id);
};
